(function(){
'use strict';
const KEY='nawaf-hq-v5';
const PROJECTS={mueen:{name:'مُعِين',liveUrl:'https://mueen-islamic-app.vercel.app/',repo:'https://github.com/uauz1/mueen-islamic-app'},qaddha:{name:'قدّها',liveUrl:'https://qaddha.vercel.app/',repo:'https://github.com/uauz1/game'}};
const EXEC_RE=/عدل|عدّل|اصلح|أصلح|اضف|أضف|احذف|حذف|نفذ|نفّذ|برمج|كود|واجهة|زر|صفحة|ميزة|مشكلة|خطأ|bug|fix|implement|update|change|deploy/i;
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'project-executor'}}))}
function activity(s,text,type='REAL'){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:'a'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),text,type,at:new Date().toISOString()});s.activity=s.activity.slice(0,150)}
function shouldExecute(t){return !!(t&&PROJECTS[t.projectId]&&t.status==='READY'&&!t.executionStartedAt&&(EXEC_RE.test(String(t.title||'')+' '+String(t.details||''))||['CUSTOM','SOLVE'].includes(String(t.kind||''))))}
async function runTask(taskId){const s=read(),t=(s.tasks||[]).find(x=>x.id===taskId);if(!t||!PROJECTS[t.projectId])return false;if(t.executionStartedAt)return false;const e=(s.employees||[]).find(x=>x.id===t.employeeId);t.executionStartedAt=new Date().toISOString();t.status='WORKING';t.progress=Math.max(12,Number(t.progress)||0);if(e){e.status='WORKING';e.task=t.title}activity(s,`${e?.name||'موظف AI'} بدأ تنفيذ تغيير حقيقي على ${PROJECTS[t.projectId].name}: ${t.title}`);write(s,'project-execution-started');
 try{
  const r=await fetch('/api/project-execute',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:t.projectId,taskId:t.id,title:t.title,instruction:t.details||t.title,employee:e?{name:e.name,role:e.role,department:e.department}:null,autoApply:true})});
  const d=await r.json().catch(()=>({}));const q=read(),task=(q.tasks||[]).find(x=>x.id===taskId),emp=(q.employees||[]).find(x=>x.id===task?.employeeId);if(!task)return false;
  task.executionResult=d;task.lastRunAt=new Date().toISOString();
  if(r.ok&&d.ok&&d.applied){task.status='COMPLETED';task.progress=100;task.aiResult={status:'COMPLETE',summary:`تم تنفيذ التعديل على ${PROJECTS[task.projectId].name} ودفع التغيير للمستودع.`,deliverable:d.execution?.proposal?.summary||'تم تطبيق التغيير بنجاح.',evidence:[...(d.execution?.proposal?.changedFiles||[]).map(x=>'ملف معدل: '+x),...(d.execution?.proposal?.checks||[]).map(x=>`${x.name}: ${x.ok?'PASS':'FAIL'}`)],nextActions:[`افتح النسخة الحية: ${d.liveUrl||PROJECTS[task.projectId].liveUrl}`],requiredTools:[],confidence:1};if(emp){emp.status='READY';emp.task=''}q.reports=Array.isArray(q.reports)?q.reports:[];q.reports.unshift({id:'r'+Date.now().toString(36),title:'تنفيذ: '+task.title,projectId:task.projectId,author:emp?.name||'AI',stage:'تم التطبيق',content:[task.aiResult.summary,task.aiResult.deliverable,(d.execution?.proposal?.changedFiles||[]).length?'الملفات:\n- '+d.execution.proposal.changedFiles.join('\n- '):''].filter(Boolean).join('\n\n'),sourceTaskId:task.id,createdAt:new Date().toISOString()});activity(q,`${emp?.name||'موظف AI'} نفّذ وطبّق: ${task.title}`)}
  else if(r.ok&&d.ok){task.status='WAITING_FOR_NAWAF';task.progress=Math.max(55,Number(task.progress)||0);task.blockedReason=d.execution?.proposal?.verificationPassed===false?'تم إنشاء تغييرات لكن التحقق لم ينجح بالكامل.':'تم تجهيز التغيير والتحقق منه لكن لم يتم دفعه للمستودع؛ يحتاج صلاحية GitHub أو مراجعة.';task.aiResult={status:'NEEDS_APPROVAL',summary:task.blockedReason,deliverable:d.execution?.proposal?.summary||'',evidence:(d.execution?.proposal?.changedFiles||[]).map(x=>'ملف مقترح: '+x),nextActions:['مراجعة التغيير ثم تطبيقه'],requiredTools:['GitHub write'],confidence:.9};if(emp)emp.status='WAITING_FOR_NAWAF';activity(q,`${emp?.name||'موظف AI'} جهّز تغييرًا على ${PROJECTS[task.projectId].name} ويحتاج خطوة أخيرة`, 'APPROVAL')}
  else{task.status='READY';task.progress=0;delete task.executionStartedAt;task.blockedReason=String(d.error||'تعذر تنفيذ التغيير');if(emp){emp.status='READY';emp.task=''}activity(q,`تعذر تنفيذ ${task.title}: ${task.blockedReason}`)}
  write(q,'project-execution-finished');return true;
 }catch(err){const q=read(),task=(q.tasks||[]).find(x=>x.id===taskId),emp=(q.employees||[]).find(x=>x.id===task?.employeeId);if(task){task.status='READY';task.progress=0;delete task.executionStartedAt;task.blockedReason=String(err?.message||err)}if(emp){emp.status='READY';emp.task=''}activity(q,'تعذر الاتصال بمحرك تنفيذ المشروع');write(q,'project-execution-error');return false}
}
let timer;function scan(){clearTimeout(timer);timer=setTimeout(()=>{const s=read(),t=(s.tasks||[]).find(shouldExecute);if(t)runTask(t.id)},350)}
window.NawafProjectExecutor={runTask,projects:PROJECTS,scan};window.addEventListener('nawaf:state-updated',scan);document.addEventListener('DOMContentLoaded',scan);setTimeout(scan,1200);
})();